{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Missing information does not establish whether repeated testing occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "70% in one reported run",
          "reason": "One reported score does not establish stability across runs."
        }
      ],
      "instrument_review": "MESA item 14: repeated testing is unknown. Item 16: the passage provides no estimate of variation across runs."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "ran the evaluation exactly once",
          "reason": "A single run establishes neither stability nor instability across runs."
        }
      ],
      "instrument_review": "MESA item 14: repeated testing explicitly did not occur. Item 16: variation across runs remains unknown."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations under the same stated conditions occurred."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA item 14: score variation was tested. Items 16 and 25: the observed range supports stability under the stated definition and tested conditions."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated testing occurred regardless of whether its results were favourable."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "MESA item 14: repeated testing occurred. Items 16 and 25: the reported variation contradicts stability under the report's definition."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence about variation across runs."
        }
      ],
      "instrument_review": "MESA item 22: installation instructions provide procedural detail. They do not resolve the missing evidence on repeated testing or score variation under items 14 and 16."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A solved more of the evaluated puzzles under the stated conditions."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish comparative general intelligence across domains."
        }
      ],
      "instrument_review": "MESA items 2, 20 and 25: the narrow comparison fits the stated intended use. Evidence supporting a broader inference is absent."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "The reported results support A's better performance on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Stating a broad intended use does not supply evidence of general intelligence across domains."
        }
      ],
      "instrument_review": "MESA item 2: the broad intended use is described. Items 9, 20 and 25: the supplied evidence covers grid performance and does not establish the broader comparison required for that use."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "The initial evidence supplies no demonstrated link between test scores and improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Improved correctness does not establish an improvement in an unmeasured safety outcome."
        }
      ],
      "instrument_review": "MESA item 20: the later trial supplies evidence beyond test scores for decision correctness in the studied workshop. Items 16 and 25: the uncertainty interval supports that comparison, while safety benefits and wider generalization remain unestablished."
    }
  ],
  "closing_note": "No material instruction was unclear. Probe labels classify evidential support; missing evidence was not treated as contradiction."
}
